function b64url(string $v):string{return rtrim(strtr(base64_encode($v),'+/','-_'),'=');}
function envelope(array $claims,string $secretKey):string{$payload=json_encode($claims,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);return b64url($payload).'.'.b64url(sodium_crypto_sign_detached($payload,$secretKey));}
